#![allow(clippy::double_must_use)] // Async methods generated by `rpc` add `must_use`.

use alloy_primitives::Sealable;
use jsonrpsee::{core::RpcResult, proc_macros::rpc, types::ErrorObjectOwned};
use reth_chainspec::{EthChainSpec, ForkCondition};
use reth_primitives_traits::AlloyBlockHeader as _;
use reth_provider::{BlockNumReader, ChainSpecProvider, HeaderProvider};
use tempo_alloy::rpc::{VerifierPcrPolicy, VerifierPcrPolicyEntry};
use tempo_chainspec::{TempoChainSpec, TempoHardfork, TempoHardforks};
use tempo_precompiles::zone_verifier::PcrPolicy;

/// Expected Nitro verifier policy served independently of accepted batch proofs.
#[rpc(server, namespace = "tempo")]
pub trait TempoVerifierPcrPolicyApi {
    /// Return this node's expected Nitro PCRs at an activated fork and its policy history.
    /// Omit `hardfork` to select the active fork. This does not inspect batch submissions.
    #[method(name = "getVerifierPcrPolicy")]
    async fn verifier_pcr_policy(&self, hardfork: Option<String>) -> RpcResult<VerifierPcrPolicy>;
}

/// Expected-policy RPC for Tempo L1 nodes (not Zone nodes).
#[derive(Debug, Clone)]
pub struct TempoVerifierPcrPolicyRpc<TProvider> {
    provider: TProvider,
}

impl<TProvider> TempoVerifierPcrPolicyRpc<TProvider> {
    /// Create a handler using the serving node's chain specification and head.
    pub fn new(provider: TProvider) -> Self {
        Self { provider }
    }
}

#[async_trait::async_trait]
impl<TProvider> TempoVerifierPcrPolicyApiServer for TempoVerifierPcrPolicyRpc<TProvider>
where
    TProvider: ChainSpecProvider<ChainSpec = TempoChainSpec>
        + BlockNumReader
        + HeaderProvider
        + Sync
        + 'static,
{
    async fn verifier_pcr_policy(&self, hardfork: Option<String>) -> RpcResult<VerifierPcrPolicy> {
        let requested = hardfork
            .map(|name| {
                name.parse::<TempoHardfork>().map_err(|_| {
                    ErrorObjectOwned::owned(
                        -32602,
                        format!("unknown Tempo hardfork: {name}"),
                        None::<()>,
                    )
                })
            })
            .transpose()?;
        let chain = self.provider.chain_spec();
        let number = self.provider.best_block_number().map_err(internal_err)?;
        let header = self
            .provider
            .header_by_number(number)
            .map_err(internal_err)?
            .ok_or_else(|| internal_err("head header not found"))?;
        let timestamp = header.timestamp();
        let active = chain.tempo_hardfork_at(timestamp);
        let selected = requested.unwrap_or(active);
        let policy = PcrPolicy::configured(chain.chain_id()).map_err(internal_err)?;
        let history: Vec<_> = TempoHardfork::VARIANTS
            .iter()
            .copied()
            .filter(|fork| *fork <= selected)
            .filter_map(|fork| {
                let activation_time = match chain.tempo_fork_activation(fork) {
                    ForkCondition::Timestamp(ts) if ts <= timestamp => {
                        (fork != TempoHardfork::Genesis).then_some(ts)
                    }
                    ForkCondition::Block(0) if fork == TempoHardfork::Genesis => None,
                    _ => return None,
                };
                Some(VerifierPcrPolicyEntry {
                    hardfork: fork.to_string(),
                    activation_time,
                    pcrs: if fork.is_t13() {
                        policy.at(fork).map(|pcrs| pcrs.map(Into::into))
                    } else {
                        None
                    },
                })
            })
            .collect();
        let selected = history
            .iter()
            .find(|entry| entry.hardfork == selected.to_string())
            .cloned()
            .ok_or_else(|| {
                ErrorObjectOwned::owned(
                    -32602,
                    format!("hardfork {selected} is not activated on this chain"),
                    None::<()>,
                )
            })?;
        Ok(VerifierPcrPolicy {
            chain_id: chain.chain_id(),
            block_number: number,
            block_hash: header.hash_slow(),
            block_timestamp: timestamp,
            active_hardfork: active.to_string(),
            selected,
            history,
        })
    }
}

fn internal_err(error: impl ToString) -> ErrorObjectOwned {
    ErrorObjectOwned::owned(-32000, error.to_string(), None::<()>)
}
